import sys
input = sys.stdin.read
data = input().split()
a, b = map(int, data)

if a < b:
    print(0)
elif a == b:
    print("infinity")
else:
    count = 0
    diff = a - b
    i = 1
    while i * i <= diff:
        if diff % i == 0:
            if i > b:
                count += 1
            if diff // i != i and diff // i > b:
                count += 1
        i += 1
    print(count)

